//! Native decoding is usable from the distinct models used by Streams and
//! Firehose Parquet. The returned Candidate is intentionally not an admitted Pool.

use bytes::Bytes;
use dex_pools::{decode_pool_creation, Candidate};
use sha2::{Digest, Sha256};
use solana_program::pubkey::Pubkey;
use substreams_solana_core::pb::sf::solana::r#type::v1 as buffa_pb;
use substreams_solana_idls::orca::whirlpool::{self, events, instructions};
use substreams_solana_idls::{pumpfun::amm as pump, spl::token};

// The actual field types/tags generated by firehose-protos (Prost 0.14 with
// .bytes(".")). Unused message fields are omitted; no fake Buffa types or
// conversion to the SDK Block are involved.
mod parquet_pb {
    #[derive(Clone, PartialEq, prost::Message)]
    pub struct Message {
        #[prost(bytes = "bytes", repeated, tag = "2")]
        pub account_keys: Vec<bytes::Bytes>,
        #[prost(message, repeated, tag = "4")]
        pub instructions: Vec<CompiledInstruction>,
    }

    #[derive(Clone, PartialEq, prost::Message)]
    pub struct CompiledInstruction {
        #[prost(uint32, tag = "1")]
        pub program_id_index: u32,
        #[prost(bytes = "bytes", tag = "2")]
        pub accounts: bytes::Bytes,
        #[prost(bytes = "bytes", tag = "3")]
        pub data: bytes::Bytes,
    }
}

struct Fixture {
    keys: Vec<Vec<u8>>,
    data: Vec<u8>,
    event: Vec<u8>,
}

fn key(n: u8) -> Pubkey {
    Pubkey::new_from_array([n; 32])
}

fn prefixed<T: borsh::BorshSerialize>(name: &str, value: &T) -> Vec<u8> {
    let mut bytes = Sha256::digest(name.as_bytes())[..8].to_vec();
    bytes.extend(borsh::to_vec(value).unwrap());
    bytes
}

fn fixture() -> Fixture {
    let token_program = bs58::decode("TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA").into_vec().unwrap();
    let token_program = Pubkey::try_from(token_program.as_slice()).unwrap();
    // Config, mints A/B, badges A/B, funder, pool, vaults A/B, fee tier,
    // token programs A/B, system and rent; program ID is the fifteenth key.
    let mut keys: Vec<Vec<u8>> = (1..=14).map(|n| vec![n; 32]).collect();
    keys[10] = token_program.to_bytes().to_vec();
    keys[11] = token_program.to_bytes().to_vec();
    keys.push(whirlpool::PROGRAM_ID.to_vec());

    Fixture {
        keys,
        data: prefixed(
            "global:initialize_pool_v2",
            &instructions::InitializePoolV2Instruction {
                tick_spacing: 64,
                initial_sqrt_price: 1 << 64,
            },
        ),
        event: prefixed(
            "event:PoolInitialized",
            &events::PoolInitialized {
                whirlpool: key(7),
                whirlpools_config: key(1),
                token_mint_a: key(2),
                token_mint_b: key(3),
                tick_spacing: 64,
                token_program_a: token_program,
                token_program_b: token_program,
                decimals_a: 6,
                decimals_b: 9,
                initial_sqrt_price: 1 << 64,
            },
        ),
    }
}

fn pump_fixture() -> Fixture {
    let mut keys: Vec<Vec<u8>> = (1..=18).map(|n| vec![n; 32]).collect();
    keys[13] = token::PROGRAM_ID.to_vec();
    keys[14] = token::PROGRAM_ID.to_vec();
    keys[17] = pump::PROGRAM_ID.to_vec();
    keys.push(pump::PROGRAM_ID.to_vec());
    let event = pump::events::CreatePoolEventV2 {
        timestamp: 1,
        index: 1,
        creator: key(3),
        base_mint: key(4),
        quote_mint: key(5),
        base_mint_decimals: 6,
        quote_mint_decimals: 9,
        base_amount_in: 10,
        quote_amount_in: 20,
        pool_base_amount: 10,
        pool_quote_amount: 20,
        minimum_liquidity: 1,
        initial_liquidity: 2,
        lp_token_amount_out: 1,
        pool_bump: 1,
        pool: key(1),
        lp_mint: key(6),
        user_base_token_account: key(7),
        user_quote_token_account: key(8),
        coin_creator: key(44),
    };
    let mut event_data = vec![0xe4, 0x45, 0xa5, 0x2e, 0x51, 0xcb, 0x9a, 0x1d];
    event_data.extend(prefixed("event:CreatePoolEvent", &event));
    Fixture {
        keys,
        data: prefixed(
            "global:create_pool",
            &pump::instructions::CreatePoolInstructionV2 {
                index: 1,
                base_amount_in: 10,
                quote_amount_in: 20,
                coin_creator: key(44),
            },
        ),
        event: event_data,
    }
}

fn current_pump_fixture() -> Fixture {
    let mut fixture = pump_fixture();
    let pump::instructions::PumpFunAmmInstruction::CreatePoolV2(base) = pump::instructions::unpack(&fixture.data).unwrap() else {
        panic!("expected V2 fixture")
    };
    fixture.data = prefixed(
        "global:create_pool",
        &pump::instructions::CreatePoolInstructionV3 {
            base,
            is_mayhem_mode: false,
            is_cashback_coin: pump::instructions::OptionBool(false),
            creator_fee_bps: pump::instructions::OptionU64(100),
            can_edit_creator_fee: pump::instructions::OptionBool(false),
            is_holder_reward: pump::instructions::OptionBool(true),
        },
    );
    let pump::events::PumpFunAmmEvent::CreatePoolEventV2(base) = pump::events::unpack(&fixture.event).unwrap() else {
        panic!("expected V2 fixture")
    };
    let mut event = vec![0xe4, 0x45, 0xa5, 0x2e, 0x51, 0xcb, 0x9a, 0x1d];
    event.extend(prefixed(
        "event:CreatePoolEvent",
        &pump::events::CreatePoolEventV3 {
            base,
            is_mayhem_mode: false,
            creator_fee_bps: 100,
            can_edit_creator_fee: false,
            is_holder_reward: true,
        },
    ));
    fixture.event = event;
    fixture
}

fn buffa_message(f: &Fixture) -> buffa_pb::Message {
    let program_index = f.keys.len() - 1;
    buffa_pb::Message {
        account_keys: f.keys.clone(),
        instructions: vec![buffa_pb::CompiledInstruction {
            program_id_index: program_index as u32,
            accounts: (0..program_index as u8).collect(),
            data: f.data.clone(),
            ..Default::default()
        }],
        ..Default::default()
    }
}

fn parquet_message(f: &Fixture) -> parquet_pb::Message {
    let program_index = f.keys.len() - 1;
    parquet_pb::Message {
        account_keys: f.keys.iter().cloned().map(Bytes::from).collect(),
        instructions: vec![parquet_pb::CompiledInstruction {
            program_id_index: program_index as u32,
            accounts: Bytes::from((0..program_index as u8).collect::<Vec<_>>()),
            data: Bytes::copy_from_slice(&f.data),
        }],
    }
}

#[test]
fn both_native_models_decode_pump_event_bytes_with_explicit_unverified_candidate_type() {
    let f = pump_fixture();
    let buffa: Candidate = from_buffa(&buffa_message(&f), &f.event).expect("Buffa candidate");
    let parquet: Candidate = from_parquet(&parquet_message(&f), &f.event).expect("Prost Bytes candidate");
    assert_eq!(buffa, parquet);
    assert_eq!(buffa.address, [1; 32]);
    assert_eq!(buffa.program_id, pump::PROGRAM_ID);
    assert_eq!(buffa.tokens[0].mint, [4; 32]);
    assert_eq!(buffa.tokens[1].mint, [5; 32]);
    assert_eq!(buffa.tokens[0].vault, Some([10; 32]));
    assert_eq!(buffa.tokens[1].vault, Some([11; 32]));

    // Decoding must reject bytes from an unrelated or truncated event. This
    // does not test success/ancestry admission, which belongs to project().
    let unrelated = fixture().event;
    assert!(from_buffa(&buffa_message(&f), &unrelated).is_none());
    assert!(from_parquet(&parquet_message(&f), &f.event[..f.event.len() - 1]).is_none());
}

#[test]
fn current_pump_creation_exports_the_same_identity_for_both_native_models() {
    let current = current_pump_fixture();
    let buffa: Candidate = from_buffa(&buffa_message(&current), &current.event).expect("current Buffa candidate");
    let parquet: Candidate = from_parquet(&parquet_message(&current), &current.event).expect("current Prost Bytes candidate");
    assert_eq!(buffa, parquet);
    let historical = pump_fixture();
    let historical = from_buffa(&buffa_message(&historical), &historical.event).unwrap();
    assert_eq!(buffa, historical);
    assert_eq!(buffa.address, [1; 32]);
    assert_eq!(buffa.tokens[0].mint, [4; 32]);
    assert_eq!(buffa.tokens[1].mint, [5; 32]);

    // A current instruction cannot borrow the older event layout as evidence.
    assert!(from_parquet(&parquet_message(&current), &pump_fixture().event).is_none());
}

fn from_buffa(message: &buffa_pb::Message, event: &[u8]) -> Option<Candidate> {
    let instruction = message.instructions.first()?;
    let program = message.account_keys.get(instruction.program_id_index as usize)?;
    let accounts = instruction
        .accounts
        .iter()
        .map(|index| message.account_keys.get(*index as usize).map(Vec::as_slice))
        .collect::<Option<Vec<_>>>()?;
    // The public decoder reads slices directly from the caller's existing model.
    assert!(std::ptr::eq(accounts[0], message.account_keys[0].as_slice()));
    decode_pool_creation(program, &instruction.data, &accounts, event)
}

fn from_parquet(message: &parquet_pb::Message, event: &[u8]) -> Option<Candidate> {
    let instruction = message.instructions.first()?;
    let program = message.account_keys.get(instruction.program_id_index as usize)?;
    let accounts = instruction
        .accounts
        .iter()
        .map(|index| message.account_keys.get(*index as usize).map(Bytes::as_ref))
        .collect::<Option<Vec<_>>>()?;
    assert!(std::ptr::eq(accounts[0], message.account_keys[0].as_ref()));
    decode_pool_creation(program, &instruction.data, &accounts, event)
}

#[test]
fn prost_bytes_and_buffa_decode_the_same_nonempty_candidate_without_wire_conversion() {
    let f = fixture();
    let buffa = from_buffa(&buffa_message(&f), &f.event).expect("Buffa candidate");
    let parquet = from_parquet(&parquet_message(&f), &f.event).expect("Prost Bytes candidate");
    assert_eq!(buffa, parquet);
    assert_eq!(buffa.address, [7; 32]);
    assert_eq!(buffa.program_id, whirlpool::PROGRAM_ID);
    assert_eq!(buffa.tokens[0].mint, [2; 32]);
    assert_eq!(buffa.tokens[1].mint, [3; 32]);
    assert_eq!(buffa.tokens[0].vault, Some([8; 32]));
    assert_eq!(buffa.tokens[1].vault, Some([9; 32]));
    assert_eq!(buffa.tokens[0].decimals, Some(6));
    assert_eq!(buffa.tokens[1].decimals, Some(9));
}

#[test]
fn independent_consumer_rejects_mismatched_event_identity_and_invalid_account_indices() {
    let f = fixture();
    let mut other_pool = f.event.clone();
    // PoolInitialized begins with its discriminator, followed by the pool key.
    other_pool[8..40].copy_from_slice(&[99; 32]);
    assert!(from_buffa(&buffa_message(&f), &other_pool).is_none());
    assert!(from_parquet(&parquet_message(&f), &other_pool).is_none());

    let mut invalid_buffa = buffa_message(&f);
    invalid_buffa.instructions[0].accounts[0] = u8::MAX;
    assert!(from_buffa(&invalid_buffa, &f.event).is_none());
    let mut invalid_parquet = parquet_message(&f);
    invalid_parquet.instructions[0].accounts = Bytes::from(vec![u8::MAX]);
    assert!(from_parquet(&invalid_parquet, &f.event).is_none());
}

fn initializer_from_buffa(message: &buffa_pb::Message, metadata: &[dex_pools::TokenAccountMetadata]) -> Option<Candidate> {
    let ix = message.instructions.first()?;
    let program = message.account_keys.get(ix.program_id_index as usize)?;
    let accounts = ix
        .accounts
        .iter()
        .map(|index| message.account_keys.get(*index as usize).map(Vec::as_slice))
        .collect::<Option<Vec<_>>>()?;
    assert!(std::ptr::eq(accounts[0], message.account_keys[0].as_slice()));
    dex_pools::decode_pool_initialization_with_token_accounts(program, &ix.data, &accounts, metadata)
}
fn initializer_from_parquet(message: &parquet_pb::Message, metadata: &[dex_pools::TokenAccountMetadata]) -> Option<Candidate> {
    let ix = message.instructions.first()?;
    let program = message.account_keys.get(ix.program_id_index as usize)?;
    let accounts = ix
        .accounts
        .iter()
        .map(|index| message.account_keys.get(*index as usize).map(Bytes::as_ref))
        .collect::<Option<Vec<_>>>()?;
    assert!(std::ptr::eq(accounts[0], message.account_keys[0].as_ref()));
    dex_pools::decode_pool_initialization_with_token_accounts(program, &ix.data, &accounts, metadata)
}

#[test]
fn both_models_retain_all_weighted_pool_mints_without_a_substreams_runtime() {
    use substreams_solana_idls::stabble;
    let mut keys: Vec<Vec<u8>> = (1..=9).map(|i| vec![i; 32]).collect();
    keys.push(stabble::PROGRAM_ID.to_vec());
    let f = Fixture {
        keys,
        data: prefixed(
            "global:initialize",
            &stabble::instructions::InitializeInstruction {
                swap_fee: 100,
                weights: vec![3000, 3000, 4000],
                max_caps: vec![10000; 3],
            },
        ),
        event: vec![],
    };
    let buffa = initializer_from_buffa(&buffa_message(&f), &[]).unwrap();
    let parquet = initializer_from_parquet(&parquet_message(&f), &[]).unwrap();
    assert_eq!(buffa, parquet);
    assert_eq!(buffa.protocol, dex_pools::Protocol::Stabble);
    assert_eq!(buffa.tokens.iter().map(|token| token.mint).collect::<Vec<_>>(), vec![[7; 32], [8; 32], [9; 32]]);
    assert!(buffa
        .tokens
        .iter()
        .all(|token| token.vault.is_none() && token.decimals.is_none() && token.token_program.is_none()));
}

#[test]
fn both_models_can_supply_explicit_vault_metadata_for_token_swap_creation() {
    use substreams_solana_idls::spl::token_swap;
    let mut keys: Vec<Vec<u8>> = (1..=8).map(|i| vec![i; 32]).collect();
    keys[7] = token::PROGRAM_ID.to_vec();
    keys.push(token_swap::PROGRAM_ID.to_vec());
    let mut data = vec![token_swap::instructions::INITIALIZE];
    data.extend(
        borsh::to_vec(&token_swap::instructions::InitializeInstruction {
            fees: token_swap::accounts::Fees {
                trade_fee_numerator: 25,
                trade_fee_denominator: 10000,
                owner_trade_fee_numerator: 5,
                owner_trade_fee_denominator: 10000,
                owner_withdraw_fee_numerator: 0,
                owner_withdraw_fee_denominator: 1,
                host_fee_numerator: 20,
                host_fee_denominator: 100,
            },
            curve_type: 0,
            curve_parameters: [0; 32],
        })
        .unwrap(),
    );
    let f = Fixture { keys, data, event: vec![] };
    let metadata = vec![
        dex_pools::TokenAccountMetadata {
            address: [3; 32],
            mint: [21; 32],
            decimals: Some(0),
            token_program: Some(token::PROGRAM_ID),
        },
        dex_pools::TokenAccountMetadata {
            address: [4; 32],
            mint: [22; 32],
            decimals: Some(9),
            token_program: Some(token::PROGRAM_ID),
        },
    ];
    assert!(initializer_from_buffa(&buffa_message(&f), &[]).is_none());
    assert!(initializer_from_parquet(&parquet_message(&f), &[]).is_none());
    let buffa = initializer_from_buffa(&buffa_message(&f), &metadata).unwrap();
    let parquet = initializer_from_parquet(&parquet_message(&f), &metadata).unwrap();
    assert_eq!(buffa, parquet);
    assert_eq!(buffa.tokens[0].decimals, Some(0));
    assert_eq!(buffa.tokens[1].mint, [22; 32]);
}
